'use strict';
function polishSiteShell(){document.body.classList.add('sitePolish');document.body.dataset.page=view.type;const header=document.querySelector('header');header.classList.add('siteHeader');header.querySelector(':scope > .row')?.classList.add('siteHeaderActions');const brand=header.firstElementChild;brand.classList.add('siteBrand');
 const aside=document.querySelector('aside');let content=$('siteSidebarContent');if(!content){content=document.createElement('div');content.id='siteSidebarContent';while(aside.firstChild)content.append(aside.firstChild);aside.append(content);const toggle=document.createElement('button');toggle.id='siteMobileNavigation';toggle.type='button';toggle.setAttribute('aria-controls',content.id);toggle.setAttribute('aria-expanded','false');toggle.innerHTML='<span>导航与档案</span><strong id="siteMobileCurrent"></strong><span class="siteNavChevron" aria-hidden="true">⌄</span>';toggle.onclick=()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));aside.classList.toggle('siteMobileOpen',open)};aside.prepend(toggle)}
 const labels={all:'全部帖子',favorite:'我的收藏',draft:'草稿箱',solo:'角色贴膜站',combo:'家产小屋',relations:'关系档案',graph:'角色关系图',gallery:'拾星馆'};$('siteMobileCurrent').textContent=view.type==='game'?game(view.id)?.name||'档案':view.type==='character'?character(view.id)?.name||'角色':labels[view.type]||'全部帖子';
 const counts={all:data.posts.filter(p=>p.status==='published').length,favorite:data.posts.filter(p=>p.favorite&&p.status==='published').length};document.querySelectorAll('#nav button[data-view]').forEach(b=>{if(b.dataset.siteStyled)return;b.dataset.siteStyled='true';const type=b.dataset.view;b.setAttribute('aria-label',b.textContent.trim());if(counts[type]!==undefined){const n=document.createElement('span');n.className='siteNavCount';n.textContent=counts[type];n.setAttribute('aria-hidden','true');b.append(n)}if(b.classList.contains('active'))b.setAttribute('aria-current','page')});
 document.querySelectorAll('#games button[data-view]').forEach(b=>{if(b.classList.contains('active'))b.setAttribute('aria-current','page')});polishSiteFeed()}
function polishSiteFeed(){foldHomePostList();document.body.dataset.page=view.type;const empty=$('feed')?.querySelector('.empty');if(empty&&!['graph','gallery','relations'].includes(view.type)&&!empty.querySelector('[data-site-compose]')){const b=document.createElement('button');b.type='button';b.className='primary siteEmptyAction';b.dataset.siteCompose='true';b.textContent='写一篇新帖';empty.append(b)}document.querySelector('main')?.setAttribute('aria-label','观星塔内容');document.querySelector('aside')?.setAttribute('aria-label','导航与档案')}
const sitePolishRender=render;render=function(){sitePolishRender();if(ready)polishSiteShell()};
const sitePolishFeed=renderFeed;renderFeed=function(){sitePolishFeed();polishSiteFeed()};
window.addEventListener('DOMContentLoaded',()=>{if(ready)polishSiteShell()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.siteCompose)$('newPost').click();if(b.dataset.view&&e.composedPath().includes(document.querySelector('aside'))&&matchMedia('(max-width:760px)').matches){document.querySelector('aside').classList.remove('siteMobileOpen');$('siteMobileNavigation')?.setAttribute('aria-expanded','false');document.querySelector('main').scrollIntoView({block:'start',behavior:'smooth'})}});

const HOME_POST_VISIBLE_COUNT=5;
let homePostListKey='',homePostListExpanded=false;
function foldHomePostList(){const feed=$('feed');if(!feed)return;feed.querySelector('.homePostFold')?.remove();if(view.type!=='all'){homePostListKey='';homePostListExpanded=false;return}const cards=[...feed.querySelectorAll(':scope > article.journalPost')],key=JSON.stringify([postPage,$('search').value,$('order').value,dateFrom,dateTo,tag,linkedSelection,cards.map(c=>c.dataset.postId)]);if(key!==homePostListKey){homePostListKey=key;homePostListExpanded=false}if(cards.length<=HOME_POST_VISIBLE_COUNT)return;const row=document.createElement('div');row.className='homePostFold';const button=document.createElement('button');button.type='button';const remaining=cards.length-HOME_POST_VISIBLE_COUNT;const draw=()=>{cards.forEach((card,i)=>{card.hidden=!homePostListExpanded&&i>=HOME_POST_VISIBLE_COUNT});button.textContent=homePostListExpanded?'收起帖子（只显示前 '+HOME_POST_VISIBLE_COUNT+' 篇）':'展开更多帖子（本页还有 '+remaining+' 篇）';button.setAttribute('aria-expanded',String(homePostListExpanded))};button.onclick=()=>{const wasOpen=homePostListExpanded;homePostListExpanded=!homePostListExpanded;draw();if(wasOpen)row.scrollIntoView({block:'nearest',behavior:'smooth'})};row.append(button);const bottom=feed.querySelector('.postPagination[aria-label="帖子底部分页"]');if(bottom)bottom.before(row);else feed.append(row);draw()}
